def min_window(s: str, t: str) -> str:
    need = {}
    for ch in t:
        need[ch] = need.get(ch, 0) + 1
    missing = len(need)   # distinct letters still lacking full coverage
    start = 0
    best_len = len(s) + 1
    best_start = 0
    for i, ch in enumerate(s):
        need[ch] = need.get(ch, 0) - 1
        if need[ch] == 0:
            missing -= 1
        while missing == 0:
            if i - start + 1 < best_len:
                best_len = i - start + 1
                best_start = start
            need[s[start]] += 1
            if need[s[start]] > 0:
                missing += 1
            start += 1
    return "" if best_len > len(s) else s[best_start:best_start + best_len]

