#include <bits/stdc++.h>
using namespace std;

string minWindow(string s, string t) {
    unordered_map<char, int> need;
    for (char ch : t) ++need[ch];
    int missing = need.size();
    int start = 0, bestLen = INT_MAX, bestStart = 0;
    for (int i = 0; i < (int)s.size(); ++i) {
        if (--need[s[i]] == 0) --missing;
        while (missing == 0) {
            if (i - start + 1 < bestLen) {
                bestLen = i - start + 1;
                bestStart = start;
            }
            if (++need[s[start]] > 0) ++missing;
            ++start;
        }
    }
    return bestLen == INT_MAX ? "" : s.substr(bestStart, bestLen);
}

