import java.util.HashMap;
import java.util.Map;

class Solution {
    public String minWindow(String s, String t) {
        Map<Character, Integer> need = new HashMap<>();
        for (char ch : t.toCharArray()) need.merge(ch, 1, Integer::sum);
        int missing = need.size();
        int start = 0, bestLen = Integer.MAX_VALUE, bestStart = 0;
        for (int i = 0; i < s.length(); ++i) {
            char ch = s.charAt(i);
            if (need.merge(ch, -1, Integer::sum) == 0) --missing;
            while (missing == 0) {
                if (i - start + 1 < bestLen) {
                    bestLen = i - start + 1;
                    bestStart = start;
                }
                char left = s.charAt(start++);
                if (need.merge(left, 1, Integer::sum) > 0) ++missing;
            }
        }
        return bestLen == Integer.MAX_VALUE ? "" : s.substring(bestStart, bestStart + bestLen);
    }
}
